/** Polls a condition for up to half a second, so a teardown waits on the socket it closed without hanging. */
export async function eventually(check: () => boolean): Promise<void> {
  for (let attempt = 0; attempt < 50 && !check(); attempt++) await new Promise(resolve => setTimeout(resolve, 10));
}

/** Closes the sockets a suite opened, then waits for each server to see them go before stopping it. */
export async function closeEngines(
  suiteServers: Array<ReturnType<typeof createServer>>,
  suiteClients: WebSocket[]
): Promise<void> {
  for (const client of suiteClients.splice(0)) client.terminate();
  for (const hal of suiteServers.splice(0)) {
    await eventually(() => hal.wss.clients.size === 0);
    await hal.stop();
  }
}

/** A store with only the five required members, so listFor can be omitted, recorded or made to throw per test. */
export function delegatingTo(inner: InMemorySessionStore): SessionStore {
  return {
    create: (sessionId, userId, options) => inner.create(sessionId, userId, options),
    get: sessionId => inner.get(sessionId),
    delete: sessionId => inner.delete(sessionId),
    count: () => inner.count(),
    clear: () => inner.clear(),
  };
}
